package com.yujing.test.suite/** * 覆盖缺口说明：框架/UI 组件类通常无法在无界面条件下自动断言， * 下列模块已刻意标为「需集成/人工」或本期不测。 */object CoverageGaps {    /** 已有用例覆盖到的能力关键字（用于总览提示） */    val coveredKeywords = listOf(        "YConvert(+bit/BCD/对象/Bitmap/流)", "YBase64", "YBase64ToHTTP", "YJson(+format)", "YCheck(+扩展)",        "YIdcard(+15转18)", "YNumber(+舍入格式化)", "YCalc", "YMoneyToCN",        "YString(+insert/分组)", "YBytes", "YConvertNumberBytes(+float/double)",        "YDate(+周起止)", "YDataLunar",        "YAes(+Base64/Hex)", "YDes", "Y3des", "YMd5", "YSha1(+文件)", "YGzip", "YEncrypt", "YOneBitCrypt", "YRsa",        "YSave", "YFileUtil(+列举追加)", "YPath(+多目录)", "YPropertiesUtils", "YObjectStorage", "YShared", "YSaveFiles",        "YUri", "YPicture(+Uri)",        "YThread", "YDelay", "YTimer(+loopIO)", "YRunOnceOfTime", "YQueue", "YAsync", "YThreadPool", "YEventCount",        "YLoop", "YReadInputStream(+长度/时间)",        "YBusUtil(+serial/clearSticky)",        "YTcp", "YUdp", "YSocketSync",        "YCreateSQL(+DML)", "YHelper", "YBaseDao", "YDB",        "YShow", "YAlertDialogUtils(+列表/单选/多选)", "YToast", "YDateDialog", "YImageDialog", "YView(+Drawable)",        "TTS(+队列)", "YSound",        "YPermissions(+清单查询)", "YTake(+拍照裁剪)", "BleClient", "BleServer", "YGoto(+多设置页)",        "YLog(+落盘/JSON)", "YScreenUtil(+sp/状态栏)", "YApp", "YUtils(+shell/Intent/剪贴板/IP)",        "YClass", "YStackTrace(+多行)", "YBitmapUtil(+圆角换色)", "YAppInfoUtils", "YFace", "YActivityUtil",        )    /** 本期不强制覆盖（基类/适配器/设备强依赖/废弃） */    val intentionallySkipped = listOf(        "base.* / YBaseActivity/Fragment/Dialog（框架基类）",        "adapter.* RecyclerView/ListView 适配器",        "contract.* 仅接口定义",        "view.YCamera / YPlayer / YFragmentManager / Auto*View / YPopupWindow（需完整页面）",        "bluetooth.YBle/YBt/YBluetooth 深度连接（已有 BLE Activity）",        "socket.YSocket 长连接（可用外网 Manual / SocketSync 回环）",        "YGps / YUsb / YNds* / YWeb* / YInstallApk* / YNoticeDownload（设备/外设/安装强依赖）",        "bus.deprecated.* / YVersionUpdate / YTts 遗留（废弃或与 TTS 重复）",        "YProgressThread / YActivityResultObserver（辅助组件）",        "YUtils.shellRoot* / openTcp（需 root）",        )    fun overviewHint(registrySize: Int, autoSize: Int): String {        return buildString {            appendLine("用例 $registrySize 条（自动 $autoSize）")            appendLine("已覆盖核心能力约 ${coveredKeywords.size} 项")            appendLine("刻意不测：")            intentionallySkipped.forEach { appendLine("· $it") }        }.trimEnd()    }}